create or replace function public.orenza_sandbox_append_audit(p_user_id uuid,p_event_type text,p_resource_type text,p_resource_id uuid,p_request_id text,p_amount numeric,p_currency text,p_metadata jsonb default '{}'::jsonb) returns uuid language plpgsql security definer set search_path=public,extensions,pg_temp as $$ declare v_previous_hash text; v_event_hash text; v_id uuid:=gen_random_uuid(); begin select event_hash into v_previous_hash from public.orenza_sandbox_audit_events order by created_at desc,id desc limit 1; v_event_hash:=encode(extensions.digest(coalesce(v_previous_hash,'')||'|'||v_id::text||'|'||coalesce(p_event_type,'')||'|'||coalesce(p_resource_type,'')||'|'||coalesce(p_resource_id::text,'')||'|'||coalesce(p_request_id,'')||'|'||coalesce(p_amount::text,'')||'|'||coalesce(p_currency,'')||'|'||coalesce(p_metadata::text,'{}'),'sha256'),'hex'); insert into public.orenza_sandbox_audit_events(id,user_id,event_type,resource_type,resource_id,request_id,amount,currency,metadata,previous_hash,event_hash) values(v_id,p_user_id,p_event_type,p_resource_type,p_resource_id,p_request_id,p_amount,p_currency,p_metadata,v_previous_hash,v_event_hash); return v_id; end; $$;
